# Constants for astronomical calculations
AU = 149.6e6  # 1 Astronomical Unit in kilometers

# Planetary data with orbital parameters (elliptical approximation)
PLANETARY_DATA = [
    {
        'name': 'Mercury',
        'semi_major_axis': 0.387,  # AU
