        'color': '#FFA500',
        'radius': 139822 / 2
    }
]

def fetch_horizons_data(body_id, start_date):
    """
    Fetch precise orbital data from NASA Horizons API
    Example body IDs: 199=Mercury, 299=Venus, 399=Earth
    """
    base_url = "https://ssd.jpl.nasa.gov/horizons_batch.cgi"
    params = {
        "batch": 1,
        "COMMAND": body_id,
        "CENTER": "@sun",
        "START_TIME": start_date.strftime("%Y-%b-%d %H:%M"),
        "STOP_TIME": start_date.strftime("%Y-%b-%d %H:%M"),
        "STEP_SIZE": "1 day",
        "OUT_UNITS": "AU-D",
        "REF_PLANE": "ecliptic",
        "REF_SYSTEM": "J2000",
        "ELEM_LABELS": "yes",
        "CSV_FORMAT": "yes"
    }

    try:
        response = requests.get(base_url, params=params)
        return parse_horizons_response(response.text)
    except Exception as e:
        print(f"Error fetching Horizons data: {e}")
        return None

def parse_horizons_response(data):
    """Parse Horizons API response (simplified for example)"""
    # Actual implementation would parse CSV response
    # This is a simplified example of orbital elements
    return {
        "semi_major_axis": 1.0,  # AU
        "eccentricity": 0.1,
        "inclination": 0.0,
        "mean_anomaly": 0.0  # radians
    }

def calculate_elliptical_position(orbital_elements, time_days):
    """
    Calculate planet position using Kepler's equation for elliptical orbits
    Returns (x, y) coordinates in AU
    """
    # Mean motion (radians per day)
    n = 2 * math.pi / 365.25  # Simplified for example

    # Mean anomaly
    M = orbital_elements["mean_anomaly"] + n * time_days

    # Solve Kepler's equation using Newton-Raphson method
    E = M
    for _ in range(100):
        E = E - (E - orbital_elements["eccentricity"] * math.sin(E) - M) / (1 - orbital_elements["eccentricity"] * math.cos(E))

    # Calculate position in orbital plane
    x = orbital_elements["semi_major_axis"] * (math.cos(E) - orbital_elements["eccentricity"])
    y = orbital_elements["semi_major_axis"] * math.sqrt(1 - orbital_elements["eccentricity"]**2) * math.sin(E)

    return (x, y)

def generate_simulation_data(timestamp=None):
    """
    Generate simulation data using multiple data sources
    Returns JSON-compatible structure
    """
    if timestamp is None:
        timestamp = datetime.now().timestamp()

    current_time = datetime.fromtimestamp(timestamp)
    days_since_epoch = (current_time - datetime(2023, 1, 1)).total_seconds() / (24 * 3600)

    simulation_data = {
        'timestamp': timestamp,
        'planets': []
    }

    for planet in PLANETARY_DATA:
        # For production: fetch real data from Horizons API
        # For this example: use simplified orbital elements
        orbital_elements = {
            "semi_major_axis": planet["semi_major_axis"],
            "eccentricity": planet["eccentricity"],
            "mean_anomaly": 0.0  # Simplified for example
        }

        x, y = calculate_elliptical_position(orbital_elements, days_since_epoch)

        simulation_data['planets'].append({
            'name': planet['name'],
            'color': planet['color'],
            'position': {
                'x': x * AU,  # Convert AU to kilometers
                'y': y * AU
            },
            'orbital_radius': planet['semi_major_axis'] * AU,
            'eccentricity': planet['eccentricity'],
            'radius': planet['radius']
        })

    return simulation_data

# Example usage: Generate current positions
if __name__ == "__main__":
    data = generate_simulation_data()
    with open('solar_system_data.json', 'w') as f:
        json.dump(data, f, indent=2)
