const x = progress * canvas.width;

// Calculate vertical scale
let scale = 1;
if (elapsed >= pulseStart && elapsed <= pulseStart + pulseDuration) {
const pulseElapsed = elapsed - pulseStart;
const halfDuration = pulseDuration / 2;
if (pulseElapsed <= halfDuration) {
scale = 1 + (pulseElapsed / halfDuration) * (maxScale - 1);
} else {
scale = maxScale - ((pulseElapsed - halfDuration) / halfDuration) * (maxScale - 1);
}
}

// Calculate waveform point
const scaledRadius = 4 * scale; // 4px base radius scaled
const y = baseline - scaledRadius; // Top bound
const waveHeight = scaledRadius * 2; // Full height from top to bottom

// Update dot position and scale
dot.style.transform = 
`translateX(${x}px) translateY(-50%) scaleY(${scale})`;

// Draw waveform
ctx.clearRect(0, 0, canvas.width, canvas.height);

// Update and maintain waveform points
points.push({x, y: baseline - scaledRadius});
if (points.length > Math.floor(canvas.width)) {
points.shift();
}

// Draw waveform path
if (points.length > 1) {
ctx.beginPath();
ctx.strokeStyle = '#0000ff';
ctx.lineWidth = 1;
ctx.moveTo(points[0].x, baseline);
ctx.lineTo(points[0].x, points[0].y);

for (let i = 1; i < points.length; i++) {
const prev = points[i - 1];
const curr = points[i];
// Draw triangle wave between points
const midX = (prev.x + curr.x) / 2;
ctx.lineTo(prev.x, curr.y);
ctx.lineTo(curr.x, curr.y);
ctx.lineTo(curr.x, baseline);
}

ctx.stroke();
}

requestAnimationFrame(animate);
}

requestAnimationFrame(animate);
</script>
