// Node.js solution using Sharp for image processing
// This code should be placed in a .js file and run in a Node.js environment

const sharp = require('sharp');
const fs = require('fs').promises;

/**
 * Adjusts the opacity of a watermark image and resizes it
 * @param {Buffer} watermarkBuffer - Original watermark image buffer
 * @param {number} width - Target width for watermark
 * @param {number} height - Target height for watermark
 * @param {number} opacity - Opacity level (0.0-1.0)
 * @returns {Promise<Buffer>} - Processed watermark buffer
 */
async function adjustWatermarkOpacity(watermarkBuffer, width, height, opacity) {
  try {
    // Resize watermark and ensure alpha channel
    const resizedWatermark = await sharp(watermarkBuffer)
      .resize(width, height)
      .ensureAlpha()
      .raw()
      .toBuffer();

    // Process alpha channel
    const { data, info } = await sharp(resizedWatermark)
      .raw()
      .toBuffer({ resolveWithObject: true });

    const { channels } = info;
    const alphaChannelIndex = channels - 1;

    // Adjust alpha channel
    for (let i = alphaChannelIndex; i < data.length; i += channels) {
      data[i] = Math.round(data[i] * opacity);
    }

    return sharp(data, {
      raw: { ...info, channels }
    }).png().toBuffer();
  } catch (error) {
    throw new Error(`Failed to adjust watermark: ${error.message}`);
  }
}

/**
 * Calculates variance of pixel intensities in a specified region
 * @param {Buffer} imageBuffer - Image buffer to analyze
 * @param {number} x - X coordinate of the region
 * @param {number} y - Y coordinate of the region
 * @param {number} width - Width of the region
 * @param {number} height - Height of the region
 * @returns {Promise<number>} - Calculated variance
 */
async function calculateRegionVariance(imageBuffer, x, y, width, height) {
  if (x < 0 || y < 0 || width <= 0 || height <= 0) {
    return Infinity;
  }

  try {
    const data = await sharp(imageBuffer)
      .extract({ left: x, top: y, width, height })
      .grayscale()
      .blur(2) // Reduce noise with Gaussian blur
      .resize(16, 16, { fit: 'inside' }) // Fixed size for consistent comparison
      .toFormat('raw')
      .toBuffer();

    const pixels = new Uint8Array(data);
    const count = pixels.length;
    let sum = 0;

    for (let p of pixels) {
      sum += p;
    }

    const mean = sum / count;
    let variance = 0;

    for (let p of pixels) {
      variance += Math.pow(p - mean, 2);
    }

    return variance / count;
  } catch (error) {
    console.warn(`Region variance calculation failed for coordinates (${x},${y}): ${error.message}`);
    return Infinity;
  }
}

/**
 * Adds a watermark to an image with smart placement
 * @param {string} imagePath - Path to the original image
 * @param {string} watermarkPath - Path to the watermark image
 * @param {string} outputImagePath - Path for the output image
 * @param {Object} options - Configuration options
 * @returns {Promise<string>} - Path to the output image
 */
async function addWatermarkToImage(imagePath, watermarkPath, outputImagePath, options = {}) {
  const {
    watermarkOpacity = 0.5,
    watermarkRatio = 0.2
  } = options;

  try {
    // Validate input parameters
    if (watermarkRatio <= 0 || watermarkRatio > 1) {
      throw new Error('watermarkRatio must be between 0 and 1');
    }

    if (watermarkOpacity < 0 || watermarkOpacity > 1) {
      throw new Error('watermarkOpacity must be between 0 and 1');
    }

    // Read original image metadata
    const imageMetadata = sharp(imagePath);
    const { width, height } = await imageMetadata.metadata();

    // Calculate watermark dimensions
    const watermarkWidth = Math.max(1, Math.floor(width * watermarkRatio));
    const watermarkHeight = Math.max(1, Math.floor(height * watermarkRatio));

    // Read and process watermark
    const watermarkBuffer = await fs.readFile(watermarkPath);
    const processedWatermark = await adjustWatermarkOpacity(
      watermarkBuffer, watermarkWidth, watermarkHeight, watermarkOpacity
    );

    // Define corners with bounds checking
    const corners = {
      'top-left': { x: 0, y: 0 },
      'top-right': { x: width - watermarkWidth, y: 0 },
      'bottom-left': { x: 0, y: height - watermarkHeight },
      'bottom-right': { x: width - watermarkWidth, y: height - watermarkHeight }
    };

    // Read original image buffer
    const imageBuffer = await imageMetadata.toBuffer();

    // Analyze each corner
    let bestCorner = 'top-left';
    let minVariance = Infinity;

    // Process corners sequentially to avoid overwhelming system
    for (const [cornerName, { x, y }] of Object.entries(corners)) {
      try {
        const variance = await calculateRegionVariance(
          imageBuffer, x, y, watermarkWidth, watermarkHeight
        );

        if (variance < minVariance) {
          minVariance = variance;
          bestCorner = cornerName;
        }
      } catch (error) {
        console.error(`Error analyzing corner ${cornerName}: ${error.message}`);
        continue;
      }
    }

    // Get coordinates for best corner
    const { x: watermarkX, y: watermarkY } = corners[bestCorner];

    // Apply watermark
    await sharp(imageBuffer)
      .composite([{
        input: processedWatermark,
        left: watermarkX,
        top: watermarkY,
        blend: 'over'
      }])
      .toFile(outputImagePath);

    return outputImagePath;
  } catch (error) {
    throw new Error(`Watermarking failed: ${error.message}`);
  }
}

// Example usage:
/*
addWatermarkToImage('input.jpg', 'watermark.png', 'output.jpg', {
  watermarkOpacity: 0.6,
  watermarkRatio: 0.25
})
  .then(result => console.log(`Watermarked image saved at: ${result}`))
  .catch(error => console.error(`Error: ${error.message}`));
*/

module.exports = addWatermarkToImage;
