import os
import bcrypt
import time
import uuid
from flask import Flask, request, jsonify
import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError, ClientError
import mysql.connector
from mysql.connector import Error, InterfaceError
from io import BytesIO

app = Flask(__name__)

def get_db_connection(retries=3, delay=2):
    """Establish database connection with exponential backoff retry mechanism"""
    for attempt in range(retries):
        try:
            cnx = mysql.connector.connect(
                host=os.environ.get('DB_HOST'),
                user=os.environ.get('DB_USER'),
                password=os.environ.get('DB_PASSWORD'),
                database=os.environ.get('DB_NAME')
            )
            return cnx
        except (Error, InterfaceError) as e:
            if attempt == retries - 1:
                print(f"Database connection failed after {retries} attempts: {e}")
                raise
            print(f"Connection attempt {attempt+1} failed. Retrying in {delay*(attempt+1)}s...")
            time.sleep(delay * (attempt + 1))
    return None

@app.route('/upload', methods=['POST'])
def upload_image():
    cnx = None
    cursor = None

    # Password verification and file validation (unchanged from previous implementation)
    password = request.form.get('password')
    titre_photo = request.form.get('titrePhoto')

    if not password or not titre_photo:
        return jsonify(success=False), 400

    stored_hash = os.environ.get('ADMIN_PASSWORD')
    if not stored_hash:
        return jsonify(success=False), 500

    if not bcrypt.checkpw(password.encode('utf-8'), stored_hash.encode('utf-8')):
        return jsonify(success=False), 401

    imageHD = request.files.get('imageHD')
    imageCompresse = request.files.get('imageCompresse')

    if not imageHD or not imageCompresse:
        return jsonify(success=False), 400

    try:
        imageHD_data = imageHD.read()
        imageCompresse_data = imageCompresse.read()
    except Exception as e:
        print(f"File read error: {e}")
        return jsonify(success=False), 500

    try:
        s3 = boto3.client('s3')
    except Exception as e:
        print(f"S3 client error: {e}")
        return jsonify(success=False), 500

    bucket_name = os.environ.get('BUCKETEER_BUCKET_NAME')
    if not bucket_name:
        return jsonify(success=False), 500

    # Upload HD image with private ACL and generate pre-signed URL
    try:
        s3_key_hd = f"hd_{uuid.uuid4()}_{imageHD.filename}"
        s3.upload_fileobj(
            BytesIO(imageHD_data),
            bucket_name,
            s3_key_hd,
            ExtraArgs={
                'ACL': 'private',
                'ContentType': 'image/jpeg',
                'ServerSideEncryption': 'AES256'
            }
        )
        pathHD = s3.generate_presigned_url(
            'get_object',
            Params={'Bucket': bucket_name, 'Key': s3_key_hd},
            ExpiresIn=604800
        )
    except (NoCredentialsError, PartialCredentialsError) as e:
        print(f"S3 credentials error: {e}")
        return jsonify(success=False), 500
    except ClientError as e:
        print(f"S3 client error: {e}")
        return jsonify(success=False), 500
    except Exception as e:
        print(f"HD upload error: {e}")
        return jsonify(success=False), 500

    # Upload compressed image with same protections
    try:
        s3_key_compresse = f"comp_{uuid.uuid4()}_{imageCompresse.filename}"
        s3.upload_fileobj(
            BytesIO(imageCompresse_data),
            bucket_name,
            s3_key_compresse,
            ExtraArgs={
                'ACL': 'private',
                'ContentType': 'image/jpeg',
                'ServerSideEncryption': 'AES256'
            }
        )
        pathCompresse = s3.generate_presigned_url(
            'get_object',
            Params={'Bucket': bucket_name, 'Key': s3_key_compresse},
            ExpiresIn=604800
        )
    except (NoCredentialsError, PartialCredentialsError) as e:
        print(f"S3 credentials error: {e}")
        return jsonify(success=False), 500
    except ClientError as e:
        print(f"S3 client error: {e}")
        return jsonify(success=False), 500
    except Exception as e:
        print(f"Compressed upload error: {e}")
        return jsonify(success=False), 500

    # Database operations with reconnection handling
    retries = 3
    for attempt in range(retries):
        try:
            if not cnx:
                cnx = get_db_connection()
                if not cnx:
                    return jsonify(success=False), 500

            cursor = cnx.cursor()
            sql = "INSERT INTO Galerie (alt, srcURL, placeHolderURL) VALUES (%s, %s, %s)"
            cursor.execute(sql, (titre_photo, pathHD, pathCompresse))
            cnx.commit()
            break  # Success, exit loop

        except (Error, InterfaceError) as e:
            if attempt < retries - 1:
                print(f"Database error: {e}. Retrying in {2*(attempt+1)}s...")
                time.sleep(2 * (attempt + 1))
                # Cleanup for next attempt
                if cursor:
                    cursor.close()
                if cnx:
                    cnx.close()
                cnx = None
                cursor = None
                continue
            else:
                print(f"Database operation failed after {retries} attempts: {e}")
                if cnx:
                    cnx.rollback()
                return jsonify(success=False), 500
        except Exception as e:
            print(f"Unexpected database error: {e}")
            if cnx:
                cnx.rollback()
            return jsonify(success=False), 500

    return jsonify(success=True)

if __name__ == '__main__':
    app.run()
